<?php
declare(strict_types=1);
if(PHP_SAPI!=='cli')exit;
foreach(['AdminAuth','Pricing','Inventory','Products','Vouchers','Orders'] as $class)require dirname(__DIR__).'/src/'.$class.'.php';
function paymentAssert(bool $ok,string $message):void{if(!$ok)throw new RuntimeException($message);}
function paymentStatus(int $status,callable $fn):void{try{$fn();}catch(HttpError $e){paymentAssert($e->status===$status,'Unexpected '.$e->status.': '.$e->getMessage());return;}throw new RuntimeException('Expected HTTP '.$status);}
$dsn=getenv('JINGO_TEST_DSN');if(!$dsn)exit(1);$opts=[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC,PDO::ATTR_EMULATE_PREPARES=>false];$user=getenv('JINGO_TEST_USER')?:'root';$password=getenv('JINGO_TEST_PASSWORD')?:'';$server=new PDO($dsn,$user,$password,$opts);$name='jingo_payments_test_'.bin2hex(random_bytes(6));$server->exec("CREATE DATABASE `$name` CHARACTER SET utf8mb4");$db=null;
try{
 $db=new PDO($dsn.';dbname='.$name,$user,$password,$opts);$db->exec("SET time_zone='+00:00'");foreach(glob(dirname(__DIR__).'/database/*.sql') as $file)foreach(explode(';',file_get_contents($file)) as $sql)if(trim($sql)!=='')$db->exec($sql);
 $product=['id'=>'p','slug'=>'test','name'=>'Vé thử','status'=>'PUBLISHED','demo'=>false,'variants'=>[['id'=>'v','name'=>'Vé','prices'=>['ADULT'=>100,'CHILD'=>0]]],'rules'=>[],'closures'=>[]];$db->prepare('INSERT INTO jingo_products(id,slug,data) VALUES (?,?,?)')->execute(['p','test',json_encode($product)]);$orders=new Orders($db);$seq=0;
 $uuid=function()use(&$seq):string{return '00000000-0000-4000-8000-'.str_pad((string)++$seq,12,'0',STR_PAD_LEFT);};
 $create=function(bool $free=false)use($orders,$uuid):array{$r=$orders->create(['requestId'=>$uuid(),'accessKey'=>str_repeat('a',64),'productId'=>'p','variantId'=>'v','date'=>'2099-06-01','quantities'=>[$free?'CHILD':'ADULT'=>1],'expectedTotal'=>$free?0:100,'contact'=>['name'=>'Payment test','email'=>'payment@example.test','phone'=>'0901234567'],'accepted'=>true]);return $orders->lookup($r);};
 $pay=function(string $reference='BANK-001',string $method='BANK',int $amount=100)use($uuid):array{return ['requestId'=>$uuid(),'version'=>1,'action'=>'PAY','note'=>'Đã kiểm tra tiền thực nhận','method'=>$method,'amount'=>$amount,'reference'=>$reference];};
 $first=$create();$input=$pay(' bank-001 ');paymentStatus(400,fn()=>$orders->act($first['id'],array_merge($input,['amount'=>99]),'admin'));paymentStatus(400,fn()=>$orders->act($first['id'],array_merge($input,['method'=>null]),'admin'));paymentStatus(400,fn()=>$orders->act($first['id'],array_merge($input,['reference'=>'CASH:fake']),'admin'));paymentStatus(400,fn()=>$orders->act($first['id'],array_merge($input,['reference'=>"BANK\n001"]),'admin'));
 $paid=$orders->act($first['id'],$input,'admin');paymentAssert($paid['paymentStatus']==='PAID'&&$paid['version']===2&&count($paid['payments'])===1&&$paid['payments'][0]['reference']==='BANK-001'&&count($paid['history'])===1,'Bank payment detail');$orders->act($first['id'],array_merge($input,['reference'=>'BANK-001']),'admin');paymentAssert(count($orders->get($first['id'])['payments'])===1,'Replay duplicated payment');paymentStatus(409,fn()=>$orders->act($first['id'],$pay('BANK-002'),'admin'));paymentStatus(409,fn()=>$orders->act($first['id'],['requestId'=>$uuid(),'version'=>2,'action'=>'CANCEL','note'=>'Cancel paid'],'admin'));
 $public=$orders->lookup(['code'=>$first['code'],'email'=>'payment@example.test']);paymentAssert($public['paymentStatus']==='PAID'&&!isset($public['payments'])&&!isset($public['history']),'Public payment privacy');paymentAssert((int)$db->query('SELECT released FROM jingo_inventory_allocations LIMIT 1')->fetchColumn()===0,'Payment released stock');
 $second=$create();paymentStatus(409,fn()=>$orders->act($second['id'],$pay('bAnK-001'),'admin'));paymentAssert($orders->get($second['id'])['version']===1&&$orders->get($second['id'])['paymentStatus']==='UNPAID','Duplicate reference changed order');
 $cash=$pay('cash','CASH');$cashResult=$orders->act($second['id'],$cash,'admin');paymentAssert($cashResult['payments'][0]['reference']==='CASH:'.$cash['requestId']&&$cashResult['payments'][0]['method']==='CASH','Cash reference');$orders->act($second['id'],$cash,'admin');
 $free=$create(true);$freeResult=$orders->act($free['id'],$pay('FREE-001','BANK',0),'admin');paymentAssert($freeResult['payments'][0]['amount']===0,'Zero-price payment');
 $cancelled=$create();$orders->act($cancelled['id'],['requestId'=>$uuid(),'version'=>1,'action'=>'CANCEL','note'=>'Cancel before payment'],'admin');paymentStatus(409,fn()=>$orders->act($cancelled['id'],$pay('CANCELLED'),'admin'));
 $rollback=$create();$rollbackInput=$pay('ROLLBACK');$before=(int)$db->query('SELECT COUNT(*) FROM jingo_payment_references')->fetchColumn();$db->exec("CREATE TRIGGER payment_history_failure BEFORE INSERT ON jingo_order_actions FOR EACH ROW SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='payment rollback'");try{$orders->act($rollback['id'],$rollbackInput,'admin');throw new RuntimeException('Expected payment rollback');}catch(PDOException $e){paymentAssert(str_contains($e->getMessage(),'payment rollback'),'Unexpected SQL error');}finally{$db->exec('DROP TRIGGER payment_history_failure');}paymentAssert((int)$db->query('SELECT COUNT(*) FROM jingo_payment_references')->fetchColumn()===$before&&$orders->get($rollback['id'])['payments']===[]&&$orders->get($rollback['id'])['paymentStatus']==='UNPAID','Payment transaction incomplete');$orders->act($rollback['id'],$rollbackInput,'admin');
 $race=function(array $jobs)use($name):array{$workers=[];foreach($jobs as [$id,$action]){$pipes=[];$process=proc_open([PHP_BINARY,__DIR__.'/payment-worker.php',$name,$id,base64_encode(json_encode($action))],[['pipe','r'],['pipe','w'],['pipe','w']],$pipes);paymentAssert(is_resource($process),'Worker start');fclose($pipes[0]);$workers[]=[$process,$pipes];}$out=[];foreach($workers as [$process,$pipes]){$out[]=stream_get_contents($pipes[1]);$error=stream_get_contents($pipes[2]);fclose($pipes[1]);fclose($pipes[2]);paymentAssert(proc_close($process)===0,'Worker error: '.$error);}sort($out);return $out;};
 $same=$create();$sameAction=$pay('REPLAY');paymentAssert($race([[$same['id'],$sameAction],[$same['id'],$sameAction]])===['paid','paid'],'Concurrent payment replay');paymentAssert(count($orders->get($same['id'])['payments'])===1,'Concurrent replay duplicated receipt');
 $left=$create();$right=$create();paymentAssert($race([[$left['id'],$pay('LAST-REFERENCE')],[$right['id'],$pay('last-reference')]])===['conflict','paid'],'Concurrent reference reused');
 $single=$create();paymentAssert($race([[$single['id'],$pay('RACE-A')],[$single['id'],$pay('RACE-B')]])===['conflict','paid'],'Concurrent double collection');paymentAssert(count($orders->get($single['id'])['payments'])===1,'Two receipts on one order');
 echo "PASS: bank/cash/free receipts, exact amount, normalized global references, replay, cancellation guard, public privacy, rollback, concurrent replay/reference/order races.\n";
}finally{if($db&&$db->inTransaction())$db->rollBack();$db=null;$server->exec("DROP DATABASE `$name`");}
